export interface Entity { id: string; [key: string]: unknown }
export interface DomainEvent { id: string; kind: string; payload: { actor?: string; operation?: Record<string, unknown>; result?: { success: boolean; error_code: string | null; data: unknown }; [key: string]: unknown }; before_hash: string | null; after_hash: string | null }
export interface OracleRow { event_id: string; operation: string; authorized: boolean; success: boolean; classification: string; operation_correct: boolean | null; reference_allowed: boolean | null; reference_error_code: string | null; violations: string[] }
export interface Oracle { status: string; trace_valid: boolean; metrics: Record<string, number>; operations: OracleRow[]; violations: unknown[]; final_state_hash: string }
export interface DomainSnapshot { domain: string; world: { seed: number; clock: string; version: string; [key: string]: unknown }; collections: Record<string, Entity[]>; summary: Record<string, number>; state_hash: string; initial_state_hash: string; exploration_source: { suite: string; instance_id: string; identity: string } | null; events: DomainEvent[]; evaluation: Oracle; invariants: unknown[]; operations_used: number; operation_budget: number }
export interface Schema { type?: string; format?: string; description?: string; minimum?: number; exclusiveMinimum?: number; default?: unknown; enum?: (string | number | boolean)[]; const?: unknown; properties?: Record<string, Schema>; items?: Schema; required?: string[]; anyOf?: Schema[] }
export interface Tool { name: string; description: string; query: boolean; params: Schema }
export interface ManualResult { event: DomainEvent & { before: unknown; after: unknown }; changes: { path: string; before: unknown; after: unknown }[]; evaluation: OracleRow; kind: string }
export interface Instance { id: string; identity: string; seed: number; initial_hash: string; recipe: string | null; task: { family: string; kind: string; message: string; structure_signature: string; semantic_signature: string } | null }
export interface Suite { key: string; suite_id: string; track: string; split: string; mode: string; tools: string[]; trials: string[]; budget: Record<string, number>; manifest_hash: string; dataset_hash: string; instance_count: number }
export interface PilotRow { instance_id: string; trial: string; run_hash: string; status: string; oracle_status: string; service_llm_calls: number; service_tool_calls: number; operation_counts: Record<string, number>; task_success?: boolean; discovery_success?: boolean; customer_turns?: number; customer_llm_calls?: number; verified_business_violation_events?: number; within_budget: boolean; family?: string }
export interface PilotReport { complete: boolean; success_rate: number | null; rows: PilotRow[] }
export interface Release { domain: string; name: string; version: string; metrics: Record<string, number>; suites: Suite[]; documents: string[]; coverage: Record<string, unknown>; service_model: string; customer_model: string; pilot: { service_report: PilotReport; discovery_report: PilotReport; interpretation: string; official_full_release_score: boolean; preflight_attempts?: unknown } }
export interface Execution { status: string; final_reply: string; model: unknown; messages: unknown[]; llm_records: unknown[]; trusted_requests: unknown; tool_records: { call_id: string; name: string; arguments: string; response: unknown; event_id?: string; dispatched?: boolean }[]; world_trace: { events: DomainEvent[] }; oracle: Oracle; [key: string]: unknown }
export interface PilotRun { run_hash: string; execution?: Execution | null; interaction?: { service?: Execution; service_execution?: Execution; status: string; customer_llm_records?: unknown[]; customer_records?: unknown[]; actions?: unknown[]; replies?: unknown[]; turns?: unknown[]; operation_audits?: unknown; format_recoveries?: number; [key: string]: unknown } | null }
